solutions.naive:
class Solution:
    def climbStairs(self, n: int) -> int:
        def ways(step: int) -> int:
            # Reached the top exactly.
            if step == n:
                return 1
            if step > n:
                return 0
            return ways(step + 1) + ways(step + 2)

        return ways(0)

solutions.better:
class Solution:
    def climbStairs(self, n: int) -> int:
        memo = {}

        def ways(step: int) -> int:
            if step == n:
                return 1
            if step > n:
                return 0
            if step not in memo:
                memo[step] = ways(step + 1) + ways(step + 2)
            return memo[step]

        return ways(0)

solutions.optimal:
class Solution:
    def climbStairs(self, n: int) -> int:
        one, two = 1, 1  # ways for the next one and next two steps
        for _ in range(n - 1):
            one, two = one + two, one
        return one

